set -uo pipefail
export LC_ALL=C

name='no-embedded-local-llm'
tag='R:no-weak-model-for-judgment'
message='This wires a local model runtime into the tool. If the work it does needs judgment, route it to the capable model the tool already reaches instead of embedding a sub-tier one. A tightly scoped mechanical pass is the exception: mark the line with the override token and say why.'
files_ere='((^|/)([^/]+/)*[^/]*\.rs$)|((^|/)([^/]+/)*[^/]*\.py$)|((^|/)([^/]+/)*[^/]*\.ts$)|((^|/)([^/]+/)*[^/]*\.js$)|((^|/)([^/]+/)*[^/]*\.go$)|((^|/)([^/]+/)*[^/]*\.java$)|((^|/)([^/]+/)*Cargo\.toml$)|((^|/)([^/]+/)*package\.json$)|((^|/)([^/]+/)*pyproject\.toml$)|((^|/)([^/]+/)*requirements[^/]*\.txt$)|((^|/)([^/]+/)*go\.mod$)'
exclude_ere='((^|/)([^/]+/)*rules/[^/]*\.md$)|((^|/)([^/]+/)*hooks-pack/.*$)|((^|/)([^/]+/)*hooks/relearn/.*$)'

fail() {
  printf '[%s] %s; the detector did not run.\n' "$name" "$1" >&2
  exit 1
}
command -v jq >/dev/null 2>&1 || fail "jq is not on PATH"

input="$(cat)"
tool_name="$(jq -r '.tool_name // ""' <<<"$input")" || fail "the payload is not JSON"
case "$tool_name" in Write|Edit|MultiEdit) ;; *) exit 0 ;; esac
file_path="$(jq -r '.tool_input.file_path // ""' <<<"$input")" || fail "the payload has no readable file_path"
file_path="${file_path//\\//}"
[ -n "$file_path" ] || exit 0

# Scope: one ERE per list, compiled by relearn from the rule's globs.
printf '%s\n' "$file_path" | grep -qE -- "$files_ere"
case $? in 0) ;; 1) exit 0 ;; *) fail "grep could not read the files pattern" ;; esac
printf '%s\n' "$file_path" | grep -qE -- "$exclude_ere"
case $? in 0) exit 0 ;; 1) ;; *) fail "grep could not read the exclude pattern" ;; esac

pattern='[Oo]llama|llama[-_.]cpp|(localhost|127\.0\.0\.1):11434'
case "$tool_name" in
  Write) new="$(jq -r '.tool_input.content // ""' <<<"$input")" ;;
  Edit) new="$(jq -r '.tool_input.new_string // ""' <<<"$input")" ;;
  MultiEdit) new="$(jq -r '[.tool_input.edits[]?.new_string] | join("\n")' <<<"$input")" ;;
esac || fail "the payload's text could not be read"

hits="$(printf '%s\n' "$new" | grep -nE -- "$pattern")"
case $? in 0) ;; 1) exit 0 ;; *) fail "grep could not read the pattern" ;; esac
# A line carrying 'allow:local-model' is a deliberate, marked exception.
hits="$(printf '%s\n' "$hits" | grep -vF -- 'allow:local-model')"
[ -n "$hits" ] || exit 0

context="$(
  printf '[%s] %s: WARNING. %s\n' "$tag" "$name" "$message"
  printf 'Offending line(s) in %s:\n%s\n' "$file_path" "$hits"
